export function rocketById(id: string): Rocket | undefined {
  return rockets.find((r) => r.id === id);
}

export function compatibleMotors(rocket: Rocket): Motor[] {
  return rocket.recommendedMotors
    .map((id) => motorById(id))
    .filter((m): m is Motor => m !== undefined);
}
